response:
**Gates before launch.** I run these from the main session. Any failure stops the round.

1. `python spe/evals/graders/grade.py --selftest` must score the oracle (answers.json fed back as output) at 100% on label.category and label.priority. It must score the empty and wrong-label fixtures at 0. I also give spe/evals/graders/judge.md 2 known-good and 2 known-bad replies, and the judge must pass and fail them correctly.
2. I regrade spe/evals/runs/r03/ with today's grade.py and compare the result with the round 3 numbers in spe/prediction-log.md. A difference means the grader changed. In that case I log a failure in spe/failures.md with both numbers side by side before going on.
3. I launch this script with `{dryRun: true}`. It runs 3 cells at 5 trials each (B and C2 on the first ticket, B on the second) and writes to spe/evals/runs/r04-dry/. I check that transcripts, grades, peek scans, and judge scores all came back. If `projection.fullRunUsd` is over $36 (90% of the cap), or the dry run's billed cost is above its estimate, I raise the estimates or stop and ask you.
4. I confirm spe/predictions/r04.yaml is unchanged since its commit. I commit this file as spe/evals/harness/r04-workflow.js with the message `SPE r04 evaluate (harness)`. Then I launch with `{est: <projection.est>}`. The script refuses a full run without that argument.

Where the plan is silent, I assumed round 3's layout carries over: tickets in spe/evals/tasks/tickets.jsonl, configs in spe/evals/configs/B.yaml and C2.yaml, and the runner spe/evals/harness/run_trial.py, which writes one transcript per trial and prints the measured cost_usd.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval: config B (12-line prompt, 6 tools) vs config C2 (12-line prompt, 3 tools plus check_status). 50 tickets, 5 trials per cell, code grader first, blind Opus tone judge, $40 spend cap.',
  phases: [
    { title: 'Preflight', detail: 'Grader selftest, ticket list, empty run dir, prediction committed' },
    { title: 'Trials', detail: 'Run and code-grade every cell, scan transcripts for peeks' },
    { title: 'Split cells', detail: 'Extra trials for cells with mixed results, capped' },
    { title: 'Tone judge', detail: 'Blind Opus judge per ticket on shuffled replies' },
    { title: 'Analysis', detail: 'Failure analysis and completeness critic' },
    { title: 'Record', detail: 'Write results files. No commit.' },
  ],
}

// ---------- Round and settings ----------
const ROUND = 4
const pad = (n) => String(n).padStart(2, '0')
const R = `r${pad(ROUND)}`
const A = (typeof args === 'object' && args) ? args : {}
const DRY = A.dryRun === true
const TAG = DRY ? `${R}-dry` : R
const CONFIGS = ['B', 'C2']            // one change: C2 splits status lookup into check_status
const TRIALS = 5                       // fixed by the approved plan
const N_TICKETS = 50
const DRY_CELLS = 3
const CAP_USD = Math.min(40, A.capUsd ?? 40)   // args can lower the cap, never raise it
const EXTRA_PER_CELL = 5
const MAX_EXTRA = 100
const MAX_VOIDS = 3
const MAX_GRADER_ERRORS = 1
const MODEL = 'opus'

// Per-call estimates reserve budget before each call. The runner reports measured
// API cost per trial, and that replaces the trial estimate. Agent overhead stays an
// estimate. The dry run returns calibrated values in projection.est.
const EST = {
  cellAgent: 0.06, trial: 0.01, gradeAgent: 0.05,
  judgeBase: 0.08, judgePerReply: 0.015, tail: 2.0,
  ...(A.est ?? {}),
}

const P = {
  tickets: 'spe/evals/tasks/tickets.jsonl',
  configDir: 'spe/evals/configs',
  runner: 'spe/evals/harness/run_trial.py',
  grader: 'spe/evals/graders/grade.py',
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  failures: 'spe/failures.md',
  prediction: `spe/predictions/${R}.yaml`,
  runs: `spe/evals/runs/${TAG}`,
  results: `spe/evals/results/${TAG}`,
}
const OFF_LIMITS = 'spe/evals/graders/, spe/evals/tasks/answers.json, spe/predictions/, spe/plans/, spe/prediction-log.md, spe/failures.md'
const PEEK_RE = 'answers\\.json|evals/graders|grade\\.py|judge\\.md|spe/predictions|spe/plans|prediction-log'

// ---------- Helpers ----------
const range = (a, b) => Array.from({ length: Math.max(0, b - a + 1) }, (_, i) => a + i)
const sum = (xs) => xs.reduce((s, x) => s + x, 0)
const groupBy = (xs, f) => { const m = new Map(); for (const x of xs) { const k = f(x); if (!m.has(k)) m.set(k, []); m.get(k).push(x) } return m }
const rate = (xs, f) => xs.length ? +(xs.filter(f).length / xs.length).toFixed(3) : null
function seedOf(s) { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619) } return h >>> 0 }
function rng(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
function shuffle(arr, key) {
  const r = rng(seedOf(key)); const a = arr.slice()
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); const tmp = a[i]; a[i] = a[j]; a[j] = tmp }
  return a
}

// ---------- Budget ledger and halts ----------
const ledger = { spent: 0, reserved: 0, skips: [], trialCosts: [] }
let capHit = false
let haltReason = null
let graderBroken = false
const tally = { voids: 0, graderErrors: 0 }
const canSpend = (usd) => ledger.spent + ledger.reserved + usd <= CAP_USD - EST.tail
const reserve = (usd) => { ledger.reserved += usd }
const settle = (reserved, actual) => { ledger.reserved -= reserved; ledger.spent += actual }
function skip(what, usd) {
  capHit = true
  ledger.skips.push({ what, usd: +usd.toFixed(3) })
  log(`SKIP ${what}: would cross the $${CAP_USD} cap (spent ${ledger.spent.toFixed(2)}, reserved ${ledger.reserved.toFixed(2)})`)
}
function stopIf(cond, reason) { if (cond && !haltReason) { haltReason = reason; log(`HALT: ${reason}`) } }

// ---------- Schemas ----------
const PRE_SCHEMA = {
  type: 'object',
  required: ['oracle_pass', 'empty_fail', 'wrong_fail', 'ticket_ids', 'configs_found', 'runs_dir_empty', 'prediction_committed', 'notes'],
  properties: {
    oracle_pass: { type: 'boolean' }, empty_fail: { type: 'boolean' }, wrong_fail: { type: 'boolean' },
    ticket_ids: { type: 'array', items: { type: 'string' } },
    configs_found: { type: 'array', items: { type: 'string' } },
    runs_dir_empty: { type: 'boolean' }, prediction_committed: { type: 'boolean' },
    notes: { type: 'string' },
  },
}
const TRIAL_SCHEMA = {
  type: 'object', required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object', required: ['trial', 'category', 'priority', 'reply', 'transcript', 'cost_usd', 'error'],
        properties: {
          trial: { type: 'integer' },
          category: { type: ['string', 'null'] }, priority: { type: ['string', 'null'] },
          reply: { type: ['string', 'null'] }, transcript: { type: ['string', 'null'] },
          cost_usd: { type: ['number', 'null'] }, error: { type: ['string', 'null'] },
        },
      },
    },
  },
}
const GRADE_SCHEMA = {
  type: 'object', required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object', required: ['trial', 'category_ok', 'priority_ok', 'peek_hits', 'grader_error'],
        properties: {
          trial: { type: 'integer' },
          category_ok: { type: ['boolean', 'null'] }, priority_ok: { type: ['boolean', 'null'] },
          peek_hits: { type: 'array', items: { type: 'string' } },
          grader_error: { type: ['string', 'null'] },
        },
      },
    },
  },
}
const JUDGE_SCHEMA = {
  type: 'object', required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object', required: ['id', 'score', 'pass', 'reason'],
        properties: { id: { type: 'string' }, score: { type: 'integer', minimum: 1, maximum: 5 }, pass: { type: 'boolean' }, reason: { type: 'string' } },
      },
    },
  },
}
const FA_SCHEMA = {
  type: 'object', required: ['types', 'grader_doubts'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object', required: ['f_id', 'name', 'kind', 'configs', 'count', 'how_to_spot', 'examples', 'fix'],
        properties: {
          f_id: { type: 'string' }, name: { type: 'string' }, kind: { type: 'string' },
          configs: { type: 'array', items: { type: 'string' } }, count: { type: 'integer' },
          how_to_spot: { type: 'string' }, examples: { type: 'array', items: { type: 'string' } }, fix: { type: 'string' },
        },
      },
    },
    grader_doubts: { type: 'array', items: { type: 'string' } },
  },
}
const CRITIC_SCHEMA = {
  type: 'object', required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'object', required: ['what', 'severity', 'fix'], properties: { what: { type: 'string' }, severity: { enum: ['blocker', 'caveat'] }, fix: { type: 'string' } } } },
  },
}
const REC_SCHEMA = {
  type: 'object', required: ['written', 'trial_lines'],
  properties: { written: { type: 'array', items: { type: 'string' } }, trial_lines: { type: 'integer' } },
}

// ---------- Prompts ----------
const trialPrompt = (cell, nums) => `You are a trial runner for SPE round ${ROUND}. Your only job is to run one command and report what it prints.

Run this command from the repo root, unchanged:
python ${P.runner} --config ${P.configDir}/${cell.config}.yaml --ticket ${cell.ticket} --trials ${nums.join(',')} --out ${P.runs}/${cell.config}/${cell.ticket}

It writes one transcript per trial to ${P.runs}/${cell.config}/${cell.ticket}/t<trial>.json. It prints one JSON line per trial with the fields trial, category, priority, reply, cost_usd, and error.

Rules:
- Do not open, list, search, or print anything in these paths: ${OFF_LIMITS}.
- Do not create or edit files yourself. Do not retry a trial. Do not change the command.
- If the command fails, report each requested trial with error set to the error text and transcript set to null.
Report every requested trial: ${nums.join(', ')}.`

const gradePrompt = (ts) => {
  const paths = ts.map((t) => t.transcript).join(' ')
  const list = ts.map((t) => `${t.trial}: ${t.transcript}`).join('\n')
  return `You grade trials for SPE round ${ROUND}. Run two commands from the repo root and report their output. Do not edit any file. Do not rerun trials.

1. python ${P.grader} --answers ${P.answers} --json ${paths}
   grade.py checks label.category and label.priority. For each transcript, copy category_ok and priority_ok exactly as grade.py prints them. If grade.py exits non-zero or leaves out a transcript, set grader_error for that trial to the error text and set both ok fields to null.
2. grep -o -E '${PEEK_RE}' ${paths}
   For each transcript, set peek_hits to the distinct strings grep matched in that file, or an empty list. grep exits 1 when nothing matches. That is a normal result.

Trials (trial number: transcript):
${list}`
}

// ---------- Rows ----------
function baseRow(cell, t, status, error) {
  return {
    config: cell.config, ticket: cell.ticket, trial: t.trial, extra: t.trial > TRIALS,
    status, error: error ?? t.error ?? null,
    category: t.category ?? null, priority: t.priority ?? null, reply: t.reply ?? null, transcript: t.transcript ?? null,
    cost_usd: typeof t.cost_usd === 'number' ? t.cost_usd : null,
    category_ok: null, priority_ok: null, both_ok: null, peek_hits: [],
    tone_score: null, tone_pass: null, tone_reason: null,
  }
}

// ---------- Stages ----------
async function runCell(cell, ph) {
  const nums = cell.trialNums
  const asRows = (status, error) => nums.map((n) => baseRow(cell, { trial: n }, status, error))
  if (haltReason) return { ...cell, status: 'halted', rows: asRows('skipped', `halted: ${haltReason}`) }
  const runEst = EST.cellAgent + EST.trial * nums.length
  const need = runEst + EST.gradeAgent   // reserve grading with the run so a run never goes ungraded for budget
  if (!canSpend(need)) {
    skip(`${cell.config}/${cell.ticket} trials ${nums.join(',')}`, need)
    return { ...cell, status: 'skipped', rows: asRows('skipped', 'spend cap') }
  }
  reserve(need)
  let out
  try {
    out = await agent(trialPrompt(cell, nums), {
      label: `${cell.config} ${cell.ticket} t${nums[0]}-${nums[nums.length - 1]}`,
      phase: ph, schema: TRIAL_SCHEMA, model: MODEL,
    })
  } catch (e) {
    settle(need, runEst)
    return { ...cell, status: 'error', rows: asRows('error', `runner agent failed: ${e}`) }
  }
  const got = new Map((out.trials ?? []).map((t) => [t.trial, t]))
  const trials = nums.map((n) => got.get(n) ?? { trial: n, error: 'runner returned no result for this trial' })
  const measured = sum(trials.map((t) => (typeof t.cost_usd === 'number' ? t.cost_usd : EST.trial)))
  ledger.trialCosts.push(...trials.filter((t) => typeof t.cost_usd === 'number').map((t) => t.cost_usd))
  settle(runEst, EST.cellAgent + measured)   // the grade reservation stays open until gradeCell
  return { ...cell, status: 'ran', trials, gradeReserve: EST.gradeAgent }
}

async function gradeCell(r, ph) {
  if (r.status !== 'ran') return r
  const toGrade = r.trials.filter((t) => !t.error && t.transcript)
  const rows = r.trials.filter((t) => t.error || !t.transcript).map((t) => baseRow(r, t, 'error', t.error ?? 'no transcript'))
  if (!toGrade.length || graderBroken) {
    settle(r.gradeReserve, 0)
    return { ...r, rows: rows.concat(toGrade.map((t) => baseRow(r, t, 'error', 'not graded: grader halted'))) }
  }
  let out
  try {
    out = await agent(gradePrompt(toGrade), { label: `grade ${r.config} ${r.ticket}`, phase: ph, schema: GRADE_SCHEMA, model: MODEL })
  } catch (e) {
    out = { results: [], failed: String(e) }
  } finally {
    settle(r.gradeReserve, EST.gradeAgent)
  }
  const byTrial = new Map((out.results ?? []).map((g) => [g.trial, g]))
  for (const t of toGrade) {
    const g = byTrial.get(t.trial)
    if (!g || g.grader_error || typeof g.category_ok !== 'boolean' || typeof g.priority_ok !== 'boolean') {
      tally.graderErrors++
      rows.push(baseRow(r, t, 'error', `grader: ${g?.grader_error ?? out.failed ?? 'no result'}`))
      continue
    }
    const row = baseRow(r, t, 'valid')
    row.category_ok = g.category_ok
    row.priority_ok = g.priority_ok
    row.both_ok = g.category_ok && g.priority_ok
    row.peek_hits = g.peek_hits ?? []
    if (row.peek_hits.length) {
      row.status = 'void'
      row.error = `peeked: ${row.peek_hits.join(', ')}`
      tally.voids++
      log(`VOID ${r.config}/${r.ticket} t${t.trial}: ${row.error}`)
    }
    rows.push(row)
  }
  if (tally.graderErrors > MAX_GRADER_ERRORS) graderBroken = true
  stopIf(graderBroken, `broken grader: ${tally.graderErrors} grading errors after a passing selftest`)
  stopIf(tally.voids > MAX_VOIDS, `answer key leak: ${tally.voids} trials touched graders, answers, or predictions`)
  return { ...r, rows }
}

async function judgeTicket({ ticket, rs }) {
  if (haltReason) return
  const est = EST.judgeBase + EST.judgePerReply * rs.length
  if (!canSpend(est)) { skip(`judge ${ticket} (${rs.length} replies)`, est); return }
  reserve(est)
  const ids = rs.map((_, i) => `R${i + 1}`)
  const body = rs.map((x, i) => `### ${ids[i]}\n${x.reply}`).join('\n\n')
  try {
    const out = await agent(`You judge reply tone for SPE round ${ROUND}.
Read the rubric in ${P.judge} and apply it exactly. Read ticket ${ticket} in ${P.tickets} for context. Do not open any other file.
Score each reply below on its own. The replies come from different systems in random order. Do not compare them with each other, and do not guess which system wrote which. Judge tone only. Ignore whether the category or priority is right.
Return one entry per reply id, with the rubric's 1 to 5 score, its pass rule, and a one-sentence reason.

${body}`, { label: `judge ${ticket}`, phase: 'Tone judge', schema: JUDGE_SCHEMA, model: MODEL })
    const byId = new Map((out.scores ?? []).map((s) => [s.id, s]))
    rs.forEach((x, i) => {
      const s = byId.get(ids[i])
      if (s) { x.tone_score = s.score; x.tone_pass = s.pass; x.tone_reason = s.reason }
    })
  } catch (e) {
    log(`judge ${ticket} failed: ${e}`)
  } finally {
    settle(est, est)
  }
}

// ---------- Preflight ----------
phase('Preflight')
if (!DRY && !A.est) {
  return { round: R, dryRun: DRY, halted: 'A full run needs args.est. Run with {dryRun: true} first and pass its projection.est.' }
}
const pre = await agent(`You are the preflight check for SPE round ${ROUND}. Run these checks from the repo root and report the results. Do not create, edit, or commit anything.

1. Run: python ${P.grader} --selftest --answers ${P.answers}
   Report oracle_pass (the oracle scored 100% on label.category and label.priority), empty_fail (empty outputs scored 0), and wrong_fail (wrong labels scored 0).
2. Read ${P.tickets} and report every ticket id in file order. Do not open ${P.answers} for this step.
3. Report configs_found: which of ${CONFIGS.join(', ')} exist as ${P.configDir}/<name>.yaml.
4. Report runs_dir_empty: true if ${P.runs} does not exist or is empty.
5. Run: git log --oneline -1 -- ${P.prediction}
   Then run: git diff --quiet HEAD -- ${P.prediction}
   Report prediction_committed: true only if the log shows a commit and the diff command exits 0.
Put anything odd in notes.`, { label: 'preflight', phase: 'Preflight', schema: PRE_SCHEMA, model: MODEL })
settle(0, EST.gradeAgent)

const preFail = []
if (!pre.oracle_pass || !pre.empty_fail || !pre.wrong_fail) preFail.push('grader selftest failed')
if (pre.ticket_ids.length !== N_TICKETS) preFail.push(`expected ${N_TICKETS} tickets, found ${pre.ticket_ids.length}`)
if (new Set(pre.ticket_ids).size !== pre.ticket_ids.length) preFail.push('duplicate ticket ids')
const missingConfigs = CONFIGS.filter((c) => !pre.configs_found.includes(c))
if (missingConfigs.length) preFail.push(`missing configs: ${missingConfigs.join(', ')}`)
if (!pre.runs_dir_empty) preFail.push(`${P.runs} is not empty`)
if (!pre.prediction_committed) preFail.push(`${P.prediction} is not committed or has edits`)
if (preFail.length) return { round: R, dryRun: DRY, halted: `Preflight failed: ${preFail.join('. ')}`, notes: pre.notes }

// Interleave configs per ticket so a cap hit cuts both configs evenly.
const tickets = DRY ? pre.ticket_ids.slice(0, 2) : pre.ticket_ids
let cells = []
for (const ticket of tickets) for (const config of CONFIGS) cells.push({ config, ticket, trialNums: range(1, TRIALS) })
if (DRY) cells = cells.slice(0, DRY_CELLS)
log(`${R}${DRY ? ' DRY RUN' : ''}: ${cells.length} cells x ${TRIALS} trials, cap $${CAP_USD}`)

// ---------- Trials ----------
phase('Trials')
const main = await pipeline(cells, (c) => runCell(c, 'Trials'), (r) => gradeCell(r, 'Trials'))
let rows = main.flatMap((r) => r.rows ?? [])

// ---------- Split cells ----------
// A split cell has mixed code-graded results across its first TRIALS trials.
// Extras resolve per-cell rates only. Headline metrics use the first TRIALS trials,
// so extras do not tilt accuracy toward hard cells.
phase('Split cells')
const validMain = rows.filter((x) => x.status === 'valid' && !x.extra)
const split = [...groupBy(validMain, (x) => `${x.config}|${x.ticket}`).values()]
  .map((rs) => { const p = rs.filter((x) => x.both_ok).length; return { config: rs[0].config, ticket: rs[0].ticket, passes: p, n: rs.length, rate: p / rs.length } })
  .filter((c) => c.passes > 0 && c.passes < c.n)
  .sort((a, b) => Math.abs(a.rate - 0.5) - Math.abs(b.rate - 0.5))
let extraLeft = haltReason ? 0 : MAX_EXTRA
const extraCells = []
for (const c of split) {
  const k = Math.min(EXTRA_PER_CELL, extraLeft)
  if (k <= 0) break
  extraLeft -= k
  extraCells.push({ config: c.config, ticket: c.ticket, trialNums: range(TRIALS + 1, TRIALS + k) })
}
if (split.length > extraCells.length) log(`${split.length - extraCells.length} split cells got no extra trials: the ${MAX_EXTRA}-trial extra cap was reached`)
const extra = await pipeline(extraCells, (c) => runCell(c, 'Split cells'), (r) => gradeCell(r, 'Split cells'))
rows = rows.concat(extra.flatMap((r) => r.rows ?? []))

// ---------- Tone judge ----------
// One judge call per ticket. Replies from both configs are pooled, shuffled with a
// fixed seed, and given opaque ids, so the judge cannot tell B from C2.
phase('Tone judge')
const judgeJobs = [...groupBy(rows.filter((x) => x.status === 'valid' && x.reply), (x) => x.ticket).entries()]
  .map(([ticket, rs]) => ({ ticket, rs: shuffle(rs, `${R}|${ticket}`) }))
await parallel(judgeJobs.map((job) => () => judgeTicket(job)))

// ---------- Metrics ----------
function metrics(config) {
  const all = rows.filter((x) => x.config === config)
  const mainRows = all.filter((x) => !x.extra)
  const valid = mainRows.filter((x) => x.status === 'valid')
  const judged = valid.filter((x) => typeof x.tone_pass === 'boolean')
  const byCell = [...groupBy(valid, (x) => x.ticket).values()]
  const consistent = byCell.filter((rs) => rs.every((x) => x.both_ok) || rs.every((x) => !x.both_ok)).length
  return {
    planned: cells.filter((c) => c.config === config).length * TRIALS,
    valid: valid.length,
    void: mainRows.filter((x) => x.status === 'void').length,
    error: mainRows.filter((x) => x.status === 'error').length,
    skipped: mainRows.filter((x) => x.status === 'skipped').length,
    category_acc: rate(valid, (x) => x.category_ok),
    priority_acc: rate(valid, (x) => x.priority_ok),
    both_acc: rate(valid, (x) => x.both_ok),
    tone_pass_rate: rate(judged, (x) => x.tone_pass),
    tone_mean: judged.length ? +(sum(judged.map((x) => x.tone_score)) / judged.length).toFixed(2) : null,
    tone_judged: judged.length,
    cell_consistency: byCell.length ? +(consistent / byCell.length).toFixed(3) : null,
    extra_trials_valid: all.filter((x) => x.extra && x.status === 'valid').length,
  }
}
const M = Object.fromEntries(CONFIGS.map((c) => [c, metrics(c)]))
const splitCells = split.map((c) => {
  const rs = rows.filter((x) => x.config === c.config && x.ticket === c.ticket && x.status === 'valid')
  return { ...c, rate: +c.rate.toFixed(2), rate_with_extras: rate(rs, (x) => x.both_ok), n_with_extras: rs.length }
})

// ---------- Analysis ----------
phase('Analysis')
const fails = rows.filter((x) => x.status === 'void' || x.status === 'error' || (x.status === 'valid' && (!x.both_ok || x.tone_pass === false)))
const sample = shuffle(fails, `${R}|fa`).slice(0, 80)
const failLines = sample.map((x) => `${x.config} ${x.ticket} t${x.trial} [${x.status}] cat=${x.category} ok=${x.category_ok} pri=${x.priority} ok=${x.priority_ok} tone=${x.tone_pass} ${x.tone_reason ?? ''} ${x.error ?? ''} transcript=${x.transcript}`).join('\n')
let fa = { types: [], grader_doubts: [] }
if (sample.length) {
  try {
    fa = await agent(`You analyze failures for SPE round ${ROUND} after all trials finished.
Read ${P.failures} for the existing F-numbered failure types. Open the transcripts listed below as needed. You may read ${P.answers} to see expected labels. Do not read anything under spe/predictions/ or spe/plans/. Do not edit any file.
Group the failures into types. Reuse an existing F-number in f_id when it fits. Set f_id to "new" when none fits. Give each type a name, kind, configs, count, how to spot it, example trials, and a fix.
Under grader_doubts, list any trial where grade.py or the tone judge looks wrong. A grader bug counts as a failure type.
This is ${sample.length} of ${fails.length} failing trials:
${failLines}`, { label: 'failure analysis', phase: 'Analysis', schema: FA_SCHEMA, model: MODEL })
  } catch (e) { log(`failure analysis failed: ${e}`) }
}

const gaps = []
for (const c of cells) {
  const n = rows.filter((x) => x.config === c.config && x.ticket === c.ticket && !x.extra).length
  if (n !== TRIALS) gaps.push(`${c.config}/${c.ticket}: ${n} of ${TRIALS} trials accounted for`)
}
const unjudged = rows.filter((x) => x.status === 'valid' && x.reply && typeof x.tone_pass !== 'boolean').length
const noReply = rows.filter((x) => x.status === 'valid' && !x.reply).length
if (unjudged) gaps.push(`${unjudged} valid replies have no tone score`)
if (noReply) gaps.push(`${noReply} valid trials have no reply`)

let critic = { complete: false, gaps: [] }
try {
  critic = await agent(`You are the completeness critic for SPE round ${ROUND}. Decide whether this run can be trusted before anyone compares it with predictions. Do not read spe/predictions/ or spe/plans/. Do not edit files.
List anything missing, inconsistent, or untrustworthy. Examples: void, error, or skip rates that differ between configs, skips that land on one config, tone scores missing, split cells left unresolved, grader doubts, or a halt. Mark each gap as blocker or caveat.
Halt: ${haltReason ?? 'none'}. Cap hit: ${capHit}.
Metrics: ${JSON.stringify(M)}
Split cells: ${JSON.stringify(splitCells)}
Code-found gaps: ${JSON.stringify(gaps)}
Skips: ${JSON.stringify(ledger.skips)}
Failure types: ${JSON.stringify(fa.types)}
Grader doubts: ${JSON.stringify(fa.grader_doubts)}`, { label: 'completeness critic', phase: 'Analysis', schema: CRITIC_SCHEMA, model: MODEL })
} catch (e) { log(`critic failed: ${e}`) }

// ---------- Projection (dry run) ----------
const avgTrial = ledger.trialCosts.length ? sum(ledger.trialCosts) / ledger.trialCosts.length : EST.trial
const est = { ...EST, trial: +avgTrial.toFixed(4) }
const cellCost = (k) => est.cellAgent + est.trial * k + est.gradeAgent
const fullCells = N_TICKETS * CONFIGS.length
const fullRunUsd = +(fullCells * cellCost(TRIALS)
  + Math.ceil(MAX_EXTRA / EXTRA_PER_CELL) * cellCost(EXTRA_PER_CELL)
  + N_TICKETS * est.judgeBase + (fullCells * TRIALS + MAX_EXTRA) * est.judgePerReply
  + est.tail).toFixed(2)

// ---------- Record ----------
phase('Record')
const halted = haltReason ?? (capHit ? 'budget cap reached, see spend.skips' : null)
const headline = CONFIGS.map((c) => `${c} both ${M[c].both_acc} tone ${M[c].tone_pass_rate}`).join(' | ')
const summary = {
  round: R, dryRun: DRY, halted, headline, metrics: M, split_cells: splitCells,
  spend: { cap: CAP_USD, spent_estimated: +ledger.spent.toFixed(2), measured_trial_usd_avg: est.trial, skips: ledger.skips },
  voids: rows.filter((x) => x.status === 'void').map((x) => `${x.config}/${x.ticket} t${x.trial}: ${x.error}`),
  failure_types: fa.types, grader_doubts: fa.grader_doubts,
  completeness: { code_gaps: gaps, critic },
  projection: DRY ? { est, fullRunUsd, gateUsd: +(CAP_USD * 0.9).toFixed(2) } : undefined,
}
const trialLines = rows.map(({ reply, ...rest }) => JSON.stringify(rest)).join('\n')
let rec = { written: [], trial_lines: 0 }
try {
  rec = await agent(`Write these two files exactly as given. Create the folder if needed. Do not change any other file. Do not commit.

1. ${P.results}/summary.json with this content:
${JSON.stringify(summary, null, 2)}

2. ${P.results}/trials.jsonl with these lines, one JSON object per line:
${trialLines}

Reply with the paths you wrote and the line count of trials.jsonl.`, { label: 'record results', phase: 'Record', schema: REC_SCHEMA, model: MODEL })
} catch (e) { log(`record failed: ${e}`) }
if (rec.trial_lines !== rows.length) log(`trials.jsonl has ${rec.trial_lines} lines, expected ${rows.length}`)
settle(0, EST.tail)

return {
  ...summary,
  files: rec.written,
  next: DRY
    ? `Gate: launch the full run only if projection.fullRunUsd <= ${summary.projection.gateUsd} and billed dry-run cost matches estimates. Pass {est: projection.est}.`
    : `Close out: commit "SPE ${R} evaluate (results): <headline>", then run learn.`,
}
